package com.tonetxo.galmap.data

import android.content.res.AssetManager
import com.tonetxo.galmap.ar.GeoArMath
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.util.zip.GZIPInputStream
import kotlin.math.cos

/**
 * Offline features shipped in assets, generated by `tools/build_dataset.py` in the same
 * shape as an Overpass response so [OverpassParser] reads both.
 */
class BundledDataset(private val assets: AssetManager) {

    @Serializable
    data class Meta(
        val south: Double,
        val west: Double,
        val north: Double,
        val east: Double,
        val generated: String,
    ) {
        /** True when the whole circle lies inside the dataset's bounding box. */
        fun covers(lat: Double, lon: Double, radiusM: Double): Boolean {
            val dLat = Math.toDegrees(radiusM / GeoArMath.EARTH_RADIUS_M)
            val dLon = dLat / cos(Math.toRadians(lat))
            return lat - dLat >= south && lat + dLat <= north && lon - dLon >= west && lon + dLon <= east
        }
    }

    private class Loaded(val meta: Meta, val features: List<GeoFeature>)

    private val json = Json { ignoreUnknownKeys = true }
    private val mutex = Mutex()
    private var loaded: Loaded? = null
    private var unavailable = false

    /** Features within [radiusM], or null when the dataset does not cover that circle. */
    suspend fun featuresAround(lat: Double, lon: Double, radiusM: Double): List<GeoFeature>? {
        val data = load() ?: return null
        if (!data.meta.covers(lat, lon, radiusM)) return null
        return withContext(Dispatchers.Default) {
            data.features.filter { GeoArMath.distanceMeters(lat, lon, it.lat, it.lon) <= radiusM }
        }
    }

    private suspend fun load(): Loaded? = mutex.withLock {
        loaded?.let { return it }
        if (unavailable) return null
        withContext(Dispatchers.IO) {
            runCatching {
                val meta = json.decodeFromString<Meta>(assets.open(META_ASSET).bufferedReader().use { it.readText() })
                val body = GZIPInputStream(assets.open(DATA_ASSET)).bufferedReader().use { it.readText() }
                Loaded(meta, OverpassParser.parse(body))
            }.getOrNull()
        }.also {
            loaded = it
            unavailable = it == null
        }
    }

    private companion object {
        const val META_ASSET = "dataset_meta.json"
        const val DATA_ASSET = "dataset.json.gz"
    }
}
